#!/usr/bin/env python3
"""Builds demo/gridlock_to_green.html: demo/page_template.html with two maps inlined, so the page runs offline and as an artifact.
  mt    the full OSM Midtown Manhattan net (248 signals; PROTOCOL_CITY_MIDTOWN_TRANSFER_20261010, Amendment MT-A1): demo/data/mt_{today,best}.json
        (DEMO_record.py through DEMO_midtown.py, seed 0, minutes 25-30); results = means over traffic seeds 0-2 of the full runs
        (research/city_sim/midtown_transfer_20261010/full/MT_{FT,BEST,LIGHT}.json); options: lights + cars, lights only.
  grid  the 4x4 test grid: demo/data/{today,best,broken,fixed}.json (seed 1400, minutes 25-30); results from the evaluation panel.
Training replays (demo/data/train_{light,fleet}.json, DEMO_record_train.py) with their learning curves (the B2D light t59 training log; the FRESH3
fleet s1413 training output; 10-episode moving average) play in the corner window on the grid."""
import json, re
from pathlib import Path
import numpy as np
ROOT = Path(__file__).resolve().parents[1]; D = ROOT / 'demo'; MT = ROOT / 'research/city_sim/midtown_transfer_20261010/full'
J = lambda p: json.loads(Path(p).read_text())


def smooth(y, k=10):
    y = np.asarray(y, float); return [round(float(np.mean(y[max(0, i - k + 1):i + 1])), 4) for i in range(len(y))]


def pct(a, b):
    return f'−{round(100 * (a - b) / a)}%' if b < a else f'+{round(100 * (b - a) / a)}%'


grid = dict(label='Test grid', count='16 lights', net=J(D / 'data/net.json'), scenes={k: J(D / f'data/{k}.json') for k in ('today', 'best', 'broken', 'fixed')},
            options=[['best', 'Lights and cars working together'], ['broken', 'Two AIs that never met'], ['fixed', 'Two AIs plus our sensing layer (TSI-G)']],
            meta=dict(today=dict(delay=56.4, caption='Lights run on a fixed cycle no matter who is waiting, so queues pile up at every corner.'),
                      best=dict(delay=16.7, caption='The light sees where the queue is; the cars know when green is coming. Cars roll up as the light turns green and keep moving.'),
                      broken=dict(delay=35.6, caption='An off-the-shelf AI light (RESCO MPLight) counts only stopped cars. AI cars that glide toward a red are invisible to it, so it makes them wait the longest.'),
                      fixed=dict(delay=29.4, caption='Same two AIs, plus TSI-G: the light senses each AI car as the human driver it replaces. No retraining, and the gliding cars are served again.')),
            sub="The same 16-intersection city, the same cars, the same five minutes of rush hour. Left: today's fixed-time lights. Right: AI traffic lights and AI cars that share signal timing.",
            results=[dict(big='−71%', what='delay per car', **{'from': '55.8 → 16.2 seconds'}), dict(big='−93%', what='time stopped at red lights', **{'from': '39.1 → 2.7 seconds per car'}),
                     dict(big='−26%', what='fuel per trip, whole city', **{'from': '93.8 → 69.8 grams'})],
            foot='SUMO traffic simulation of a 16-signal grid, peak demand. Results: 20 unseen traffic days × 5 independently trained AI lights × 4 AI fleets, fuel model HBEFA4; the maps replay minutes 25–30 of one day. In the right panel half the cars are the AI fleet. Lights: AI keep-or-switch controllers; cars: an AI eco-driving fleet that receives a calibrated forecast of each light.')
maps = dict(grid=grid); order = ['grid']
if (D / 'data/mt_today.json').exists() and (MT / 'MT_FT.json').exists() and (MT / 'MT_BEST.json').exists():
    ft, be, li = J(MT / 'MT_FT.json'), J(MT / 'MT_BEST.json'), J(MT / 'MT_LIGHT.json'); assert ft['status'] == be['status'] == li['status'] == 'COMPLETE'
    fr, br, lr = ({r['seed']: r for r in x['rows']} for x in (ft, be, li)); seeds = sorted(fr); assert seeds == sorted(br) == sorted(lr) == [0, 1, 2]
    m = lambda R, k: float(np.mean([R[s][k] for s in seeds]))

    def res(R):
        tl0, tl1, w0, w1, f0, f1 = m(fr, 'timeloss'), m(R, 'timeloss'), m(fr, 'waiting'), m(R, 'waiting'), m(fr, 'fuel') / 1000, m(R, 'fuel') / 1000
        return [dict(big=pct(tl0, tl1), what='delay per car', **{'from': f'{tl0:.0f} → {tl1:.0f} seconds'}),
                dict(big=pct(w0, w1), what='time stopped at red lights', **{'from': f'{w0:.0f} → {w1:.0f} seconds per car'}),
                dict(big=pct(f0, f1), what='fuel per trip, whole city', **{'from': f'{f0:.0f} → {f1:.0f} grams'})]
    base = ('SUMO simulation of the full OpenStreetMap extract of Midtown Manhattan (248 signals; signal programs generated by SUMO, not the city\'s timing plans), '
            '4 800 random trips per hour for one hour, 3 traffic days, fuel model HBEFA4; the maps replay minutes 25–30 of day 1. The AI lights run the 224 two-phase '
            'intersections, the others keep their programs; ')
    maps['mt'] = dict(label='Midtown Manhattan', count='248 lights, real street map', net=J(D / 'data/net_midtown.json'),
                      scenes=dict(today=J(D / 'data/mt_today.json'), best=J(D / 'data/mt_best.json'), light=J(D / 'data/mt_light.json')),
                      options=[['best', 'AI lights + AI cars'], ['light', 'AI lights, human drivers']],
                      meta=dict(today=dict(delay=fr[0]['timeloss'], caption='Fixed signal cycles across 248 intersections: queues spill back from one block into the next.'),
                                best=dict(delay=br[0]['timeloss'], caption='The same AI lights and AI cars, trained only on the small grid, dropped unchanged into Midtown. Avenues keep flowing.'),
                                light=dict(delay=lr[0]['timeloss'], caption='The AI lights alone, with every car driven by a human: the lights read the queues on a map they never saw.')),
                      sub='The real street map of Midtown Manhattan, from 23rd to 66th Street (OpenStreetMap), 4 800 trips an hour. Left: fixed-time lights. Right: AI that never saw this map in training.',
                      results=dict(best=res(br), light=res(lr)),
                      foot=dict(best=base + 'half the cars are the AI eco-driving fleet. Both AIs were trained only on the 16-signal grid and run here without retraining.',
                                light=base + 'every car is a human driver. The AI lights were trained only on the 16-signal grid and run here without retraining.'))
    order = ['mt', 'grid']
data = dict(maps=maps, order=order)
if (D / 'data/train_light.json').exists() and (D / 'data/train_fleet.json').exists():
    lt = J(D / 'data/train_light.json'); fl = J(D / 'data/train_fleet.json')
    lc = [r['mean_r'] for r in J(ROOT / 'research/city_sim/w19_20261008/lights/RL-H_t59.log.json')]
    fc = [float(x.group(1)) for x in re.finditer(r' ep \d+ .*?meanR (-?[\d.]+)', (ROOT / 'research/city_sim/w15_20261007/fresh3/fleets/L11_s1413.out').read_text())]
    data['train'] = dict(map='grid', light=dict(episodes=lt['episodes'], tls=lt['tls'], n=len(lc), curve=smooth(lc), label='light reward per decision, rising = less delay'),
                         fleet=dict(episodes=fl['episodes'], tls=fl['tls'], n=len(fc), curve=smooth(fc), label='car reward per decision, rising = less fuel'))
blob = json.dumps(data, separators=(',', ':'), ensure_ascii=False).replace('</', '<\\/')
html = (D / 'page_template.html').read_text().replace('__DATA__', blob)
(D / 'gridlock_to_green.html').write_text(html)
print('wrote', D / 'gridlock_to_green.html', round(len(html.encode()) / 2 ** 20, 2), 'MB; maps', order, '; training replay' if 'train' in data else '; no training replay')
if 'mt' in maps:
    for k, R in maps['mt']['results'].items():
        print('midtown', k, '(3 seeds):', [(r['big'], r['from']) for r in R])
